"""R6 model handoff used by the local single-writer batch.

Consumes registered model events and closes already submitted jobs. No permission issuance, job
submission, budget reservation, automatic retry or scientific acceptance here.
Registered CPU analysis workers are supported; resource/live dispatch and next-plan phases remain incomplete.
"""
from pathlib import Path
import argparse
import json
import os
import subprocess
import sys
import time

from rlflow.jobs import identity, owns
from rlflow.store import sha
from tools.r6_recovery import Journal, RecoveryError, checked, file_pin
from tools.r6_model_worker import validate_request
from tools.r6_worker_processes import cleanup_verified

ROOT=Path(__file__).resolve().parents[1]


def worker_environment():
    return dict(os.environ,PYTHONDONTWRITEBYTECODE='1',CUDA_VISIBLE_DEVICES='',
                PYTHONPATH='.:tools/rlflow',GIT_TERMINAL_PROMPT='0')


def verified_decision(journal,key):
    """Receipt recording is separate from validating the returned decision."""
    entry=journal.read()['events'][key]
    receipt=json.loads(checked(entry['receipt']).read_text())
    if receipt.get('exit_code')!=0 or receipt.get('error') is not None or receipt.get('schema_valid') is not True:
        raise RecoveryError('MODEL_FAILED_PRESERVE_RECEIPT')
    if not cleanup_verified(receipt.get('cleanup')):
        raise RecoveryError('MODEL_CLEANUP_NOT_VERIFIED')
    for keyname in ('events','stderr','last_message'):
        checked(receipt[keyname])
    _,_,_,schema=validate_request(entry['request'])
    result=json.loads(checked(receipt['last_message']).read_text())
    import jsonschema
    jsonschema.validate(result,schema)
    return result


def complete_model_receipt(journal,key,receipt_path):
    """Atomically consume a receipt and clear only its verified terminal marker.

Also repairs old consume-before-phase-save states. Failed results remain failed;
unverified cleanup retains the active marker and its recorded receipt.
"""
    journal.require_writer()
    observed=journal.observe(key,receipt_path=receipt_path)
    if observed['action'] not in ('ACCEPT_RECEIPT','ALREADY_CONSUMED'):
        raise RecoveryError('MODEL_RECEIPT_NOT_READY')
    pin=observed['receipt'];receipt=json.loads(checked(pin).read_text())
    state=journal.read();entry=state['events'][key]
    if (entry['kind']!='model' or receipt.get('event_key')!=key
            or receipt.get('request_sha256')!=sha(entry['request'])
            or type(receipt.get('exit_code')) is not int
            or (entry['process'] is not None and receipt.get('process')!=entry['process'])):
        raise RecoveryError('MODEL_RECEIPT_IDENTITY')
    terminal_cleanup=cleanup_verified(receipt.get('cleanup')) and not any(owns(i) for i in
        [entry.get('process'),receipt.get('process'),receipt.get('child_identity'),
         *receipt.get('cleanup',{}).get('observed_identities',[])])
    changed=entry.get('receipt') is None
    if changed:entry.update(receipt=pin,status='RECEIPT_RECORDED')
    if terminal_cleanup and state.get('current_model_event')==key:
        state['current_model_event']=None
        if state.get('status')=='MODEL_REVIEW':state['status']='MODEL_RECEIPT_RECORDED'
        changed=True
    if changed:journal.save(state)
    if not terminal_cleanup:raise RecoveryError('MODEL_CLEANUP_NOT_VERIFIED')
    return verified_decision(journal,key)


def model_handoff(journal,key,*,poll_seconds=15):
    """Caller holds the sole writer lock throughout the read-only review.

    Dispatch claim survives a crash before Popen; that ambiguous event is never
    retried. After Popen, worker.json permits exact reattachment even if the
    controller died before binding the PID into state. A receipt permits closing
    an already exited worker. STOP is handled by the worker and never removed.
    """
    journal.require_writer()
    if not 0<poll_seconds<=60:raise ValueError('LOCAL_POLL_INTERVAL')
    state=journal.read();entry=state['events'][key]
    if entry['kind']!='model':raise RecoveryError('MODEL_EVENT_REQUIRED')
    call=journal.directory/'calls'/key
    receipt_path=call/'receipt.json'
    process=None
    if entry['receipt']:
        return complete_model_receipt(journal,key,receipt_path)
    if not entry.get('dispatch_claim'):
        if any(e['kind']=='cpu' and ((e.get('dispatch_claim') and not e.get('receipt'))
                or any(not c.get('receipt') for c in e.get('sample_claims',{}).values()))
                for e in state['events'].values()):
            raise RecoveryError('CPU_WORKER_HANDOFF_UNRESOLVED')
        journal.require_dispatch_budget()
        if entry['process'] is not None or entry['status']!='INTENT' or call.exists():
            raise RecoveryError('UNCLAIMED_SIDE_EFFECT_REQUIRES_RECONCILIATION')
        validate_request(entry['request'])
        entry['dispatch_claim']={'controller':identity(os.getpid()),'time':time.time(),
                                 'worker':file_pin(ROOT/'tools/r6_model_worker.py')}
        state.update(status='MODEL_REVIEW',current_model_event=key,controller_identity=identity(os.getpid()))
        journal.save(state)
        process=subprocess.Popen([sys.executable,'-B','-m','tools.r6_model_worker',
            str(journal.directory.resolve()),key],cwd=ROOT,env=worker_environment(),
            stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,
            start_new_session=True)
        live=identity(process.pid)
        if live is not None:journal.bind_process(key,live)
    while True:
        if process is not None:process.poll() # Reap our child before checking owns().
        entry=journal.read()['events'][key]
        # Worker identity is persisted before any model side effect. The event
        # key plus exact Linux start/boot identity prevents PID-only attachment.
        worker_path=call/'worker.json'
        if entry['process'] is None and worker_path.exists():
            worker=json.loads(worker_path.read_text())
            if worker['event_key']!=key:raise RecoveryError('WORKER_EVENT_MISMATCH')
            if owns(worker['identity']):journal.bind_process(key,worker['identity'])
        action=journal.observe(key,receipt_path=receipt_path)['action']
        if action in ('ACCEPT_RECEIPT','ALREADY_CONSUMED'):
            return complete_model_receipt(journal,key,receipt_path)
        if action=='RECONCILE':
            # A live process owned by this invocation may not have created its
            # worker.json yet; its exact Popen identity is already bound above.
            raise RecoveryError('MODEL_AMBIGUOUS_NO_RETRY')
        if action not in ('WAIT_OWNED_WORKER','WAIT_OWNED_EXIT','CANCEL_OWNED'):
            raise RecoveryError('UNEXPECTED_MODEL_OBSERVATION: '+action)
        # STOP is observed by the worker's bounded local loop, including cleanup.
        # No second model is called to ask whether the first one has finished.
        time.sleep(poll_seconds)


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('directory',type=Path);ap.add_argument('event_key')
    action=ap.add_mutually_exclusive_group()
    action.add_argument('--job-store',type=Path,help='Close an existing exact job in this rlflow Store; never submit')
    action.add_argument('--inventory-store',type=Path,help='Inventory exact closed-job originals; no GPU queries')
    action.add_argument('--postrun-keys',nargs=2,metavar=('GPU_EVENT','PROCESS_EVENT'),help='Complete two registered postrun queries for event_key job')
    action.add_argument('--decision',action='store_true',help='Recover a registered post-analysis decision and validate its proposal')
    action.add_argument('--cpu-analysis',action='store_true',help='Execute/recover a registered CPU analysis event; never call a model')
    action.add_argument('--analysis-report',type=Path,help='Bind an existing CPU motion replay report; no scientific acceptance')
    ap.add_argument('--analysis-store',type=Path,help='Exact Store for --analysis-report')
    a=ap.parse_args();journal=Journal(a.directory.resolve())
    if bool(a.analysis_report is not None or a.cpu_analysis or a.decision) != (a.analysis_store is not None):
        ap.error('--analysis-report, --cpu-analysis or --decision requires --analysis-store')
    with journal.writer():
        if a.decision:
            from rlflow.store import Store
            from tools.r6_decision import handoff
            result=handoff(journal,a.event_key,Store(a.analysis_store.resolve()))
        elif a.cpu_analysis:
            from rlflow.store import Store
            from tools.r6_cpu_analysis import handoff
            result=handoff(journal,a.event_key,Store(a.analysis_store.resolve()))
        elif a.analysis_report is not None:
            from rlflow.store import Store
            from tools.r6_analysis_binding import record_analysis
            result=record_analysis(journal,a.event_key,file_pin(a.analysis_report),Store(a.analysis_store.resolve()))
        elif a.postrun_keys is not None:
            from tools.r6_postrun import complete_postruns
            result=complete_postruns(journal,a.event_key,a.postrun_keys)
        elif a.inventory_store is not None:
            from rlflow.store import Store
            from tools.r6_job_inventory import record_inventory
            result=record_inventory(journal,a.event_key,Store(a.inventory_store.resolve()))
        elif a.job_store is None:
            result=model_handoff(journal,a.event_key)
        else:
            from rlflow.store import Store
            from tools.r6_job_handoff import job_handoff
            result=job_handoff(journal,a.event_key,Store(a.job_store.resolve()))
    print(json.dumps(result,ensure_ascii=False))


if __name__=='__main__':main()
"""R6 recovery journal, reusing rlflow atomic persistence and process identity.

This is not a launcher. The controller must hold this lock before calling any
mutation. An intent without authoritative completion never authorizes a retry.
"""
from contextlib import contextmanager
from pathlib import Path
import fcntl
import hashlib
import json
import os

from rlflow.jobs import identity, owns
from rlflow.store import atomic, canonical, sha
from tools.r6_budget import reserve, admissible


class RecoveryError(RuntimeError):
    pass


def file_pin(path):
    path = Path(path).resolve()
    with path.open('rb') as stream:
        digest = hashlib.file_digest(stream, 'sha256').hexdigest()
    return {'path': str(path), 'sha256': digest}


def checked(pin):
    path = Path(pin['path'])
    if path.is_symlink() or file_pin(path) != pin:
        raise RecoveryError('PIN_DRIFT')
    return path


class Journal:
    def __init__(self, directory, stop_paths=()):
        self.directory = Path(directory)
        self.path = self.directory / 'state.json'
        self.stop_paths = [self.directory / 'STOP', *map(Path, stop_paths)]
        self._lock = None
        self._owner_pid = None

    @contextmanager
    def writer(self):
        if self._lock is not None:
            raise RecoveryError('NESTED_WRITER')
        self.directory.mkdir(parents=True, exist_ok=True)
        with (self.directory / 'writer.lock').open('a') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            self._lock, self._owner_pid = lock, os.getpid()
            try:
                yield self
            finally:
                self._lock = self._owner_pid = None
                fcntl.flock(lock, fcntl.LOCK_UN)

    def require_writer(self):
        if self._lock is None or self._owner_pid != os.getpid():
            raise RecoveryError('SINGLE_WRITER_REQUIRED')

    def stopped(self):
        return [str(p) for p in self.stop_paths if p.exists()]

    def guard(self):
        self.require_writer()
        if self.stopped():
            raise RecoveryError('STOP_NEW_ACTIONS')

    def read(self):
        return json.loads(self.path.read_text())

    def save(self, state):
        self.require_writer()
        atomic(self.path, canonical(state) + b'\n')

    def initialize(self, budget):
        self.guard()
        if self.path.exists():
            raise RecoveryError('USE_EXISTING_STATE')
        self.save({'schema_version': 'r6-recovery/1', 'goal_id': budget['goal_id'],
                   'controller_identity': identity(os.getpid()), 'budget': budget,
                   'events': {}, 'duplicate_events_rejected': 0,
                   'status': 'CPU_PREPARE', 'current_job': None})

    def intent(self, event, *, kind, request, resources, purpose, free_disk_bytes):
        """Persist request and reservation in one transaction before side effects.

        Returns (key, fresh). False means inspect existing work, never launch.
        Input hash covers the full request, including executable/prompt/schema.
        """
        self.guard()
        if kind not in {'job', 'model', 'settle', 'postrun', 'cpu'}:
            raise RecoveryError('UNKNOWN_EVENT_KIND')
        if event.get('input_sha256') != sha(request):
            raise RecoveryError('REQUEST_IDENTITY_MISMATCH')
        state = self.read()
        key = sha(event)
        entry = {'identity': event, 'kind': kind, 'request': request,
                 'resources': resources, 'purpose': purpose}
        if kind == 'job' and any(e['kind'] == 'job' and e['identity']['job_id'] == event['job_id'] and k != key
                for k, e in state['events'].items()):
            raise RecoveryError('JOB_ALREADY_BOUND_TO_EVENT')
        if key in state['events']:
            previous = state['events'][key]
            if any(previous[k] != v for k, v in entry.items()):
                raise RecoveryError('EVENT_REPLAY_DRIFT')
            admissible(state['budget'])
            state['duplicate_events_rejected'] += 1
            self.save(state)
            return key, False
        state['budget'] = reserve(state['budget'], event_key=event, resources=resources,
                                  purpose=purpose, free_disk_bytes=free_disk_bytes)
        state['events'][key] = {**entry, 'status': 'INTENT', 'process': None,
                                'receipt': None}
        self.save(state)
        return key, True

    def require_dispatch_budget(self):
        self.guard()
        admissible(self.read()['budget'])

    def canonical_job(self, key, *, state=None):
        state = self.read() if state is None else state
        entry = state['events'][key]
        if entry['kind'] != 'job':raise RecoveryError('JOB_EVENT_REQUIRED')
        aliases = [k for k,e in state['events'].items()
                   if e['kind'] == 'job' and e['identity']['job_id'] == entry['identity']['job_id']]
        if aliases != [key]:raise RecoveryError('JOB_EVENT_ALIAS_REQUIRES_RECONCILIATION')
        return entry

    def bind_process(self, key, process):
        self.require_writer()
        if not owns(process):
            raise RecoveryError('PROCESS_IDENTITY_NOT_LIVE')
        state = self.read()
        entry = state['events'][key]
        if entry['status'] != 'INTENT' or entry['process'] is not None:
            raise RecoveryError('PROCESS_ALREADY_BOUND')
        entry.update(process=process, status='RUNNING')
        self.save(state)

    def observe(self, key, *, receipt_path=None, exact_job=None):
        """Read-only recovery decision based on a receipt or a live exact handle.

        STOP never suppresses observation/cleanup of an existing owned job.
        A callback result must include the exact event job ID and request hash.
        A job receipt is not settlement; returned COMPLETE only closes this event.
        """
        entry = self.read()['events'][key]
        if entry['receipt']:
            checked(entry['receipt'])
            return {'action': 'ALREADY_CONSUMED', 'receipt': entry['receipt']}
        if receipt_path is not None and Path(receipt_path).exists():
            try:
                raw = Path(receipt_path).read_bytes()
                receipt = json.loads(raw)
            except (ValueError, UnicodeError):
                return {'action': 'RECONCILE', 'reason': 'PARTIAL_RECEIPT_NO_RETRY'}
            if not isinstance(receipt, dict):
                raise RecoveryError('INVALID_RECEIPT_OBJECT')
            if receipt.get('event_key') != key or receipt.get('request_sha256') != sha(entry['request']):
                raise RecoveryError('RECEIPT_IDENTITY_MISMATCH')
            if type(receipt.get('exit_code')) is not int:
                raise RecoveryError('INVALID_RECEIPT_EXIT_CODE')
            if entry['process'] is not None and receipt.get('process') != entry['process']:
                raise RecoveryError('RECEIPT_PROCESS_MISMATCH')
            if owns(entry['process']) or owns(receipt.get('process')):
                return {'action': 'WAIT_OWNED_EXIT'}
            return {'action': 'ACCEPT_RECEIPT', 'receipt': {
                'path': str(Path(receipt_path).resolve()),
                'sha256': hashlib.sha256(raw).hexdigest()}}
        if exact_job is not None:
            expected = entry['identity']
            if exact_job.get('job_id') != expected['job_id'] or exact_job.get('input_sha256') != expected['input_sha256']:
                raise RecoveryError('EXACT_JOB_IDENTITY_MISMATCH')
            if type(exact_job.get('terminal')) is not bool:
                raise RecoveryError('INVALID_JOB_TERMINAL_FLAG')
            if exact_job['terminal']:
                return {'action': 'CLOSE_AND_SETTLE', 'job_id': expected['job_id']}
            if owns(exact_job.get('process')):
                return {'action': 'CANCEL_OWNED' if self.stopped() else 'WAIT_EXACT_JOB',
                        'job_id': expected['job_id']}
            return {'action': 'RECONCILE', 'reason': 'JOB_HANDLE_MISSING_NO_RETRY'}
        if owns(entry['process']):
            return {'action': 'CANCEL_OWNED' if self.stopped() else 'WAIT_OWNED_WORKER'}
        return {'action': 'RECONCILE', 'reason': 'INTENT_WITHOUT_LIVE_HANDLE_OR_RECEIPT'}

    def consume(self, key, receipt_path):
        self.require_writer()
        observed = self.observe(key, receipt_path=receipt_path)
        if observed['action'] == 'ALREADY_CONSUMED':
            return False
        if observed['action'] != 'ACCEPT_RECEIPT':
            raise RecoveryError('RECEIPT_NOT_READY: ' + observed['action'])
        checked(observed['receipt'])
        state = self.read()
        entry = state['events'][key]
        entry.update(receipt=observed['receipt'], status='RECEIPT_RECORDED')
        # Even nonzero exits retain the full reservation. Decision/schema and
        # evidence acceptance are separate gates in the eventual controller.
        self.save(state)
        return True
"""Inventory one already closed job and complete its two exact postrun queries.

Optional CPU analysis and one registered proposal-only decision follow.
No submission, automatic retry, budget refund or science acceptance.
"""
import argparse
import json
from pathlib import Path
import shutil

from tools.r6_job_inventory import record_inventory
from tools.r6_postrun import register_postruns, complete_postruns
from tools.r6_recovery import Journal, RecoveryError, checked, file_pin


def finalize(journal, key, store, executable, *, free_disk_bytes):
    journal.require_writer()
    checked(executable)
    inventory=record_inventory(journal,key,store)
    state=journal.read();job=journal.canonical_job(key,state=state)
    existing={}
    for event_key,event in state['events'].items():
        if event['kind']=='postrun' and event['identity']['job_id']==job['identity']['job_id']:
            ordinal=event['request'].get('ordinal')
            expected=dict(job_event_key=key,closure=job['closure'],inventory=job['inventory'],
                          executable=executable,ordinal=ordinal)
            if type(ordinal) is not int or ordinal not in (0,1) or ordinal in existing or event['request']!=expected:
                raise RecoveryError('FINALIZE_POSTRUN_BINDING')
            existing[ordinal]=event_key
    # Recover existing events directly, including after STOP. Registration of a
    # missing ordinal still traverses the normal STOP and budget gates.
    keys=([existing[0],existing[1]] if len(existing)==2 else
          register_postruns(journal,key,executable,free_disk_bytes=free_disk_bytes))
    postrun=complete_postruns(journal,key,keys)
    return dict(inventory=inventory,postrun=postrun,scientific_acceptance=False)


def analyze(journal, key, store, *, free_disk_bytes, python=None, program=None, timeout_seconds=3600):
    """Register once or reconnect the same bounded CPU analysis event.

Overrides exist for isolated CPU fixtures; the existing analysis validator
requires the frozen interpreter/analyzer for every real-mode job.
"""
    from tools import r6_cpu_analysis as cpu
    journal.require_writer()
    state=journal.read();job=journal.canonical_job(key,state=state)
    existing=[event_key for event_key,event in state['events'].items()
        if event['kind']=='cpu' and event['identity']['job_id']==job['identity']['job_id']
        and event['identity']['role']=='cpu-analysis']
    expected=dict(python=file_pin(cpu.PYTHON) if python is None else python,
        program=file_pin(cpu.ROOT/cpu.SOURCES[0]) if program is None else program,
        timeout_seconds=timeout_seconds)
    if existing:
        if len(existing)!=1:raise RecoveryError('FINALIZE_ANALYSIS_ALIAS')
        event_key=existing[0];entry,_=cpu.validate(journal,event_key)
        if (entry['request']['job_event_key']!=key
                or any(entry['request'][name]!=value for name,value in expected.items())):
            raise RecoveryError('FINALIZE_ANALYSIS_BINDING')
    else:
        event_key=cpu.register_analysis(journal,key,store,free_disk_bytes=free_disk_bytes,**expected)
    return cpu.handoff(journal,event_key,store)


def decide(journal, key, store, executable, *, free_disk_bytes, sandbox='read-only', poll_seconds=15):
    """Register/recover the exact post-analysis model event, never a next job."""
    from tools import r6_decision as decision
    from tools.r6_analysis_binding import bind_analysis
    from rlflow.store import sha
    journal.require_writer()
    state=journal.read();job=journal.canonical_job(key,state=state)
    path=checked(executable)
    if state['goal_id']=='R6-CPU-TEST-FIXTURE':
        if not path.is_relative_to(journal.directory.parent.resolve()):
            raise RecoveryError('FINALIZE_DECISION_FIXTURE_EXECUTABLE')
    elif executable!={'path':str(decision.CLI),'sha256':decision.CLI_SHA}:
        raise RecoveryError('FINALIZE_DECISION_PINNED_CLI')
    existing=[event_key for event_key,event in state['events'].items()
        if event['kind']=='model' and event['identity']['job_id']==job['identity']['job_id']
        and event['identity']['role']=='post-analysis-decision']
    if len(existing)>1:raise RecoveryError('FINALIZE_DECISION_ALIAS')
    if not existing or not state['events'][existing[0]].get('decision_input'):
        if existing and (state['events'][existing[0]].get('dispatch_claim') or state['events'][existing[0]].get('receipt')):
            raise RecoveryError('FINALIZE_DECISION_INPUT_AMBIGUOUS')
        event_key=decision.register(journal,key,store,executable=executable,
            free_disk_bytes=free_disk_bytes,sandbox=sandbox)
    else:
        event_key=existing[0];entry=state['events'][event_key];packet_input=entry['decision_input']
        expected=dict(prompt=packet_input['prompt'],schema=file_pin(decision.SCHEMA),
            executable=executable,cwd=str(decision.ROOT),sandbox=sandbox,
            timeout_seconds=3600,output_cap_bytes=decision.MODEL_CAP,
            stop_paths=[str((journal.directory.parent/'STOP').resolve()),str((journal.directory/'STOP').resolve())])
        identity=dict(goal_id=state['goal_id'],event_id='DECISION:'+key,
            job_id=job['identity']['job_id'],input_sha256=sha(expected),role='post-analysis-decision')
        if (entry['request']!=expected or entry['identity']!=identity or sha(identity)!=event_key
                or packet_input['job_event_key']!=key):
            raise RecoveryError('FINALIZE_DECISION_BINDING')
        packet=json.loads(checked(packet_input['packet']).read_text())
        binding=json.loads(checked(job['analysis']).read_text())
        if (packet['analysis']!=job['analysis']
                or binding!=bind_analysis(job,key,binding['report'],store)):
            raise RecoveryError('FINALIZE_DECISION_ANALYSIS_DRIFT')
    return decision.handoff(journal,event_key,store,poll_seconds=poll_seconds)


def finish_and_decide(journal, key, store, query_executable, decision_executable, *,
                      free_disk_bytes, sandbox='read-only', poll_seconds=15):
    """Resume a registered decision before revisiting earlier completed phases."""
    journal.require_writer()
    state=journal.read();job=journal.canonical_job(key,state=state)
    has_decision=any(event['kind']=='model' and event['identity']['job_id']==job['identity']['job_id']
        and event['identity']['role']=='post-analysis-decision' for event in state['events'].values())
    if not has_decision:
        finalize(journal,key,store,query_executable,free_disk_bytes=free_disk_bytes)
        analyze(journal,key,store,free_disk_bytes=free_disk_bytes)
    proposal=decide(journal,key,store,decision_executable,free_disk_bytes=free_disk_bytes,
                    sandbox=sandbox,poll_seconds=poll_seconds)
    job=journal.canonical_job(key)
    return dict(inventory=json.loads(checked(job['inventory']).read_text()),
        postrun=json.loads(checked(job['postrun']).read_text()),
        analysis=json.loads(checked(job['analysis']).read_text()),decision=proposal,
        scientific_acceptance=False)


def main(argv=None):
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('directory',type=Path);parser.add_argument('event_key')
    parser.add_argument('--store',type=Path,required=True)
    parser.add_argument('--executable',type=Path,required=True)
    parser.add_argument('--analyze',action='store_true',help='Run/recover the bounded CPU replay after postrun')
    parser.add_argument('--decision-executable',type=Path,help='After analysis, run/recover one exact proposal-only model decision')
    parser.add_argument('--decision-sandbox',choices=['read-only','danger-full-access'],default='read-only')
    args=parser.parse_args(argv)
    if args.decision_executable is not None and not args.analyze:
        parser.error('--decision-executable requires --analyze')
    from rlflow.store import Store
    journal=Journal(args.directory.resolve())
    with journal.writer():
        root=args.store.resolve(strict=True)
